 36→@Component({
 37→  selector: "tfc-player-view",
 38→  changeDetection: ChangeDetectionStrategy.OnPush,
 39→  providers: [ExerciseStore, TickService],
 40→  imports: [
 41→    ClockDisplayComponent,
