@layer components {
  .logs-list {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    font-family: var(--font-mono, monospace);
    font-size: 0.75rem;
  }

  .log-entry {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.375rem 0.5rem;
    border-left: 3px solid var(--color-border);
    border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
    background: oklch(from var(--color-muted) l c h / 0.3);
  }

  .log-entry[data-type="phase_change"] {
    border-left-color: var(--color-muted-foreground);
  }

  .log-entry[data-type="event_change"] {
    border-left-color: var(--color-info, oklch(0.65 0.15 240));
  }

  .log-entry[data-type="decision_opened"],
  .log-entry[data-type="decision_closed"] {
    border-left-color: var(--color-warning);
  }

  .log-entry[data-type="system_state_change"] {
    border-left-color: var(--color-success);
  }

  .log-entry[data-type="issue_change"] {
    border-left-color: var(--color-destructive);
  }

  .log-time {
    color: var(--color-muted-foreground);
    min-width: 3.5rem;
  }

  .log-action {
    font-weight: 500;
    color: var(--color-foreground);
  }

  .log-target {
    color: var(--color-muted-foreground);
    font-style: italic;
  }

  .logs-empty {
    color: var(--color-muted-foreground);
    text-align: center;
    padding: 2rem 1rem;
    font-family: var(--font-sans);
    font-size: 0.875rem;
  }
