import { ComponentFixture, TestBed } from "@angular/core/testing";
import { Component, signal } from "@angular/core";
import { SystemStatusBoardComponent } from "./system-status-board.component";
import type { SystemSnapshot } from "../core/generated/state-changes.types";

@Component({
  selector: "test-host",
  imports: [SystemStatusBoardComponent],
  template: `<tfc-system-status-board [systems]="systems()" />`,
})
class TestHost {
  systems = signal<SystemSnapshot[]>([]);
}

function makeSys(overrides: Partial<SystemSnapshot> = {}): SystemSnapshot {
  return {
    system_id: "nav",
    label: "NAV",
    category: "sensor",
    power: true,
    operational: "green",
    ...overrides,
  };
}

describe("SystemStatusBoardComponent", () => {
  let fixture: ComponentFixture<TestHost>;
  let host: TestHost;

  beforeEach(async () => {
    await TestBed.configureTestingModule({
      imports: [TestHost],
    }).compileComponents();
    fixture = TestBed.createComponent(TestHost);
    host = fixture.componentInstance;
    fixture.detectChanges();
  });

  it("should render one row per system", () => {
    host.systems.set([
      makeSys({ system_id: "nav", label: "NAV" }),
      makeSys({ system_id: "comms", label: "COMMS", power: false, operational: "red" }),
    ]);
    fixture.detectChanges();
    const rows = fixture.nativeElement.querySelectorAll('[data-testid="system-row"]');
    expect(rows.length).toBe(2);
  });

  it("should show power-off styling when power is false", () => {
    host.systems.set([makeSys({ power: false })]);
    fixture.detectChanges();
    const row = fixture.nativeElement.querySelector('[data-testid="system-row"]');
    expect(row.getAttribute("data-power")).toBe("false");
  });

  it("should set data-operational attribute", () => {
    host.systems.set([makeSys({ operational: "yellow" })]);
    fixture.detectChanges();
    const row = fixture.nativeElement.querySelector('[data-testid="system-row"]');
    expect(row.getAttribute("data-operational")).toBe("yellow");
  });

  it("should display system label", () => {
    host.systems.set([makeSys({ label: "COMMS" })]);
    fixture.detectChanges();
    expect(fixture.nativeElement.textContent).toContain("COMMS");
  });

  it("should show nothing when systems array is empty", () => {
    host.systems.set([]);
    fixture.detectChanges();
    const rows = fixture.nativeElement.querySelectorAll('[data-testid="system-row"]');
    expect(rows.length).toBe(0);
  });
});

