/**
 * Playwright e2e tests for player view — gaps 3, 5, 6.
 *
 * Gap 3: Participant identity wired end-to-end
 * Gap 5: Score persisted in snapshot on reconnect
 * Gap 6: PlayerType resolved from scenario roles
 */
import { test, expect, mockParticipant } from "../fixtures/base.fixture";

const exerciseId = 800;

const baseSnapshot = {
  exercise_id: exerciseId,
  title: "Test Exercise",
  phase: "running",
  time: {
    play_time_ms: 60_000,
    real_time_ms: 60_000,
    factor: 1,
    paused: false,
  },
  events: [],
  issues: [],
  decisions: [],
  score: null,
};

const snapshotWithScore = {
  ...baseSnapshot,
  score: {
    total_score: 25.0,
    penalty_ms: 400.0,
    turn_number: 3,
    next_decision_time_ms: 299_600,
  },
};

const contextWithRoles = {
  title: "Silent Wake",
  description: "Naval cyber exercise",
  briefing: "You are aboard...",
  objectives: ["Defend the ship"],
  rules: ["No cheating"],
  roles: [
    { id: "co", label: "Commanding Officer", player_type: "decision_maker" },
    { id: "nav", label: "Navigator", player_type: "advisor" },
    { id: "ops", label: "Operations", player_type: "advisor" },
  ],
};

function playerUrl(participantId: string, role = "player"): string {
  return `/player?exerciseId=${exerciseId}&participantId=${participantId}&role=${role}`;
}

async function installPlayerMocks(
  page: import("@playwright/test").Page,
  snapshot = baseSnapshot,
  context = contextWithRoles,
): Promise<void> {
  const decisions = (snapshot as Record<string, unknown>)["decisions"] ?? [];

  // Mock engine snapshot
  await page.route(
    `**/api/exercises/${exerciseId}/engine/snapshot`,
    async (route) => {
      await route.fulfill({
        status: 200,
        contentType: "application/json",
        body: JSON.stringify(snapshot),
      });
    },
  );

  // Mock engine context
  await page.route(
    `**/api/exercises/${exerciseId}/engine/context`,
    async (route) => {
      await route.fulfill({
        status: 200,
        contentType: "application/json",
        body: JSON.stringify(context),
      });
    },
  );

  // Mock decisions list (skip engine sub-paths)
  await page.route(`**/api/decisions*`, async (route) => {
    if (route.request().url().includes("/engine/")) {
      await route.fallback();
      return;
    }
    await route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify([]),
    });
  });

  // Mock engine decisions
  await page.route(
    `**/api/exercises/${exerciseId}/engine/decisions`,
    async (route) => {
      if (route.request().method() === "GET") {
        await route.fulfill({
          status: 200,
          contentType: "application/json",
          body: JSON.stringify(decisions),
        });
      } else {
        await route.fallback();
      }
    },
  );

  // Swallow WebSocket
  await page.route("**/ws?*", (route) => route.abort("connectionrefused"));
  await page.route("**/ws", (route) => route.abort("connectionrefused"));
}

// ── Gap 5: Score in snapshot ──────────────────────────────────────────

test.describe("Gap 5 — Score in snapshot @player", () => {
  test("displays score from snapshot on load", async ({ page }) => {
    await installPlayerMocks(page, snapshotWithScore);
    await page.goto(playerUrl("alice-01"));

    // Turn banner should show turn 3
    await expect(page.locator("tfc-turn-banner")).toContainText("Turn 3");
  });

  test("no score shown when snapshot has null score", async ({ page }) => {
    await installPlayerMocks(page, baseSnapshot);
    await page.goto(playerUrl("alice-01"));

    // No turn banner should appear
    await expect(page.getByText(/Turn \d/)).not.toBeVisible();
  });
});

// ── Gap 6: PlayerType from scenario roles ─────────────────────────────

test.describe("Gap 6 — PlayerType from scenario roles @player", () => {
  test("decision-maker sees role label in footer", async ({ page }) => {
    await installPlayerMocks(page, baseSnapshot, contextWithRoles);
    await page.goto(playerUrl("co-01", "co"));

    await expect(
      page.getByText("You are the Commanding Officer"),
    ).toBeVisible();
  });

  test("advisor sees role label in footer", async ({ page }) => {
    await installPlayerMocks(page, baseSnapshot, contextWithRoles);
    await page.goto(playerUrl("nav-01", "nav"));

    await expect(page.getByText("You are the Navigator")).toBeVisible();
  });
});

// ── Gap 3: Participant identity ───────────────────────────────────────

test.describe("Gap 3 — Participant identity @player @waiting-room", () => {
  test("waiting room passes participantId and role to player view", async ({
    page,
    mockApi,
  }) => {
    const alice = mockParticipant({
      id: "alice-99",
      display_name: "Alice",
      role: "player",
    });
    mockApi.seed(exerciseId, [alice], "simple_collaborative");
    await mockApi.install();

    // Mock engine endpoints for player view
    await installPlayerMocks(page);

    // Navigate from waiting room to player view
    await page.goto(
      `/waiting-room?exerciseId=${exerciseId}&participantId=${alice.id}`,
    );
    await page.getByRole("button", { name: /Start Exercise/ }).click();

    // Verify URL contains participantId and role
    await expect(page).toHaveURL(/\/player/);
    await expect(page).toHaveURL(/participantId=alice-99/);
    await expect(page).toHaveURL(/role=player/);
  });
});

/**
 * Property-style Playwright tests for 2-player mode.
 *
 * Tests the waiting room toggle + role selector, and the player view
 * behaviour when the all_advisors synthetic role is active.
 *
 * Invariants verified:
 * - 2 Players button visible only in simple_collaborative
 * - Clicking 2 Players button shows role selectors with Decision Maker / All Advisors
 * - Start disabled until exactly 2 participants with one of each role
 * - All-advisors player sees tabbed all-advisors-panel, NOT advisor panel
 * - All-advisors player sees all open decisions (bypasses target_roles)
 * - Decision-maker sees composite-key advisor bubbles with role labels
 * - Footer text matches synthetic role
 */
import { test, expect, mockParticipant } from "../fixtures/base.fixture";
import type { Page } from "@playwright/test";

const EX_ID = 1100;

const SCENARIO_ROLES = [
  {
    id: "co",
    label: "Commanding Officer",
    player_type: "decision_maker" as const,
  },
  { id: "nav", label: "Navigator", player_type: "advisor" as const },
  { id: "ops", label: "Operations", player_type: "advisor" as const },
  { id: "cyops", label: "CyOps", player_type: "advisor" as const },
];

function seedScenarioWithRoles(
  mockApi: import("../fixtures/base.fixture").MockApi,
  gameMode: string,
): void {
  if (!mockApi.exerciseMap.has(EX_ID)) {
    mockApi.seedExercise(EX_ID, gameMode, EX_ID);
  }
  if (!mockApi.scenarios.find((s) => s.id === EX_ID)) {
    mockApi.seedScenario({
      id: EX_ID,
      title: "Test Scenario",
      description: "",
      domain_id: null,
      content: { roles: SCENARIO_ROLES, game_mode: gameMode },
      version: 1,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    });
  }
}

// ── State building blocks ─────────────────────────────────────────────

const TIME = {
  play_time_ms: 120_000,
  real_time_ms: 120_000,
  factor: 1,
  paused: false,
};

const SCORE = {
  total_score: 10.0,
  penalty_ms: 200.0,
  turn_number: 2,
  next_decision_time_ms: 180_000,
};

const CONTEXT = {
  title: "Silent Wake",
  description: "Naval cyber exercise",
  briefing: "You are aboard the USS Sentinel.",
  objectives: ["Defend the ship"],
  rules: ["Time is critical"],
  roles: SCENARIO_ROLES,
};

const DECISION_OPEN = {
  id: "dec1",
  event_id: "e1",
  issue_id: "iss1",
  title: "Evasive Action",
  description: "Choose a maneuver.",
  question_type: "single_choice",
  options: [
    { id: "opt-a", label: "Hard starboard", score: 10 },
    { id: "opt-b", label: "All stop", score: 5 },
    { id: "opt-c", label: "Maintain course", score: -2 },
  ],
  completion_mode: "first_response",
  target_roles: [] as string[],
  timeout_ms: 300_000,
  status: "open",
  opened_at_pt_ms: 60_000,
  closed_at_pt_ms: null,
  recommendations: {},
};

const DECISION_TARGETED_CO = {
  ...DECISION_OPEN,
  id: "dec-co",
  title: "CO Only Decision",
  target_roles: ["co"],
};

const DECISION_WITH_COMPOSITE_RECS = {
  ...DECISION_OPEN,
  id: "dec-recs",
  title: "Decision With Role Recs",
  recommendations: {
    "all-adv-01:nav": "opt-a",
    "all-adv-01:ops": "opt-b",
    "all-adv-01:cyops": "opt-c",
  },
};

// ── Helpers ───────────────────────────────────────────────────────────

interface SnapshotOpts {
  phase?: string;
  decisions?: (typeof DECISION_OPEN)[];
  score?: typeof SCORE | null;
}

function snapshot(opts: SnapshotOpts = {}) {
  return {
    exercise_id: EX_ID,
    title: "Test Exercise",
    phase: opts.phase ?? "running",
    time: TIME,
    events: [],
    issues: [],
    decisions: opts.decisions ?? [],
    score: opts.score ?? null,
  };
}

function playerUrl(participantId: string, role: string): string {
  return `/player?exerciseId=${EX_ID}&participantId=${participantId}&role=${role}`;
}

async function installPlayerMocks(
  page: Page,
  snap: ReturnType<typeof snapshot>,
  ctx = CONTEXT,
): Promise<void> {
  const decisions = snap.decisions ?? [];
  await page.route(`**/api/exercises/${EX_ID}/engine/snapshot`, (route) =>
    route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify(snap),
    }),
  );
  await page.route(`**/api/exercises/${EX_ID}/engine/context`, (route) =>
    route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify(ctx),
    }),
  );
  await page.route("**/api/decisions*", async (route) => {
    if (route.request().url().includes("/engine/")) {
      await route.fallback();
      return;
    }
    await route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify([]),
    });
  });
  await page.route(
    `**/api/exercises/${EX_ID}/engine/decisions`,
    async (route) => {
      if (route.request().method() === "GET") {
        await route.fulfill({
          status: 200,
          contentType: "application/json",
          body: JSON.stringify(decisions),
        });
      } else {
        await route.fallback();
      }
    },
  );
  await page.route("**/ws?*", (route) => route.abort("connectionrefused"));
  await page.route("**/ws", (route) => route.abort("connectionrefused"));
  await page.route("**/api/domain-configs", (route) =>
    route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify([]),
    }),
  );
}

function collabWaitingRoomUrl(participantId: string): string {
  return `/waiting-room?exerciseId=${EX_ID}&participantId=${participantId}`;
}

// ── 1. WAITING ROOM — 2 PLAYER MODE TOGGLE ──────────────────────────
//    Checkbox visible only in simple_collaborative mode.
//    Hidden in classic mode.

test.describe("Waiting room — 2 Players button visibility @waiting-room @two-player", () => {
  test("2 Players button visible in simple_collaborative mode", async ({
    page,
