// ── 8. DECISION TARGETING ─────────────────────────────────────────────
//    Decisions with target_roles only shown to matching roles.

test.describe("Decision targeting — role-filtered visibility @player", () => {
  test("targeted decision visible to matching role", async ({ page }) => {
