// ── 10. COMBINED STATE INVARIANTS ─────────────────────────────────────
//    Full cross-product: score + events + issues + decision + role
//    All invariants must hold simultaneously.

test.describe("Combined state — all invariants hold together @player", () => {
  test("advisor with score, events, issues, and open decision", async ({
    page,
  }) => {
    await installMocks(
      page,
      snapshot({
        phase: "running",
        score: SCORE_TURN_3,
        events: [EVENT_RUNNING, EVENT_COMPLETED, EVENT_SCHEDULED],
        issues: [
          ISSUE_ACTIVE_RELEASED,
          ISSUE_ACTIVE_UNRELEASED,
          ISSUE_RESOLVED,
        ],
        decisions: [DECISION_WITH_RECS],
      }),
    );
    await page.goto(playerUrl("nav-01", "nav"));

    // Header always visible
    await expect(page.locator(".player-header__title")).toBeVisible();
    await expect(page.locator("tfc-phase-badge")).toContainText("running");

    // Score visible
    await expect(page.locator("tfc-turn-banner")).toContainText("Turn 3");
    await expect(page.locator("tfc-score-bar")).toBeVisible();

    // Events: running + completed visible, scheduled hidden
    await expect(page.getByText("NAV Report")).toBeVisible();
    await expect(page.getByText("EO Sighting")).toBeVisible();
    await expect(page.getByText("Future Inject")).not.toBeVisible();

    // Issues: released visible, unreleased hidden
    await expect(page.getByText("Radar Failure")).toBeVisible();
    await expect(page.getByText("Resolved Issue")).toBeVisible();
    await expect(page.getByText("Hidden Issue")).not.toBeVisible();

    // Decision: advisor panel with [Advisor] prefix
    await expect(page.locator("tfc-decision-panel")).toBeAttached();
    await expect(page.getByText("[Advisor] Decision With Recs")).toBeVisible();

    // Advisor does NOT see bubbles
    await expect(page.locator("tfc-advisor-bubbles")).not.toBeAttached();

    // Footer: role label for advisor (Navigator)
    await expect(page.getByText("You are the Navigator")).toBeVisible();

    // Context visible
    await expect(
      page.getByText("You are aboard the USS Sentinel."),
    ).toBeVisible();
  });

  test("decision-maker with score, events, issues, and open decision with recs", async ({
    page,
  }) => {
    await installMocks(
      page,
      snapshot({
        phase: "running",
        score: SCORE_TURN_3,
        events: [EVENT_RUNNING],
        issues: [ISSUE_ACTIVE_RELEASED],
        decisions: [DECISION_WITH_RECS],
      }),
    );
    await page.goto(playerUrl("co-01", "co"));

    // Score visible
    await expect(page.locator("tfc-turn-banner")).toContainText("Turn 3");

    // Events visible
    await expect(page.getByText("NAV Report")).toBeVisible();

    // Issues visible
    await expect(page.getByText("Radar Failure")).toBeVisible();

    // Decision: DM panel (no [Advisor] prefix) + advisor bubbles
    await expect(page.locator("tfc-decision-panel")).toBeVisible();
    await expect(page.getByText("[Advisor]")).not.toBeVisible();
    await expect(page.getByText("Decision With Recs")).toBeVisible();
    await expect(page.locator("tfc-advisor-bubbles")).toBeVisible();
    await expect(page.locator(".advisor-bubble__count")).toContainText("2");

    // Footer: role label for decision maker (Commanding Officer)
    await expect(
      page.getByText("You are the Commanding Officer"),
    ).toBeVisible();
  });

  test("paused with no score, no events, no issues, no decisions", async ({
    page,
  }) => {
    await installMocks(
      page,
      snapshot({
        phase: "paused",
        time: TIME_PAUSED,
        score: null,
        events: [],
        issues: [],
        decisions: [],
      }),
    );
    await page.goto(playerUrl("nav-01", "nav"));

    // Phase badge shows paused
    await expect(page.locator("tfc-phase-badge")).toContainText("paused");

    // No score elements
    await expect(page.locator("tfc-turn-banner")).not.toBeVisible();
    await expect(page.locator("tfc-score-bar")).not.toBeVisible();

    // Empty states
    await expect(page.getByText("No Events intercepted.")).toBeVisible();
    await expect(page.getByText("No Issues detected. Systems nominal.")).toBeVisible();

    // No decision overlay
    await expect(page.locator("tfc-decision-panel")).not.toBeVisible();

    // Issue details placeholder
    await expect(
      page.getByText("Select a threat vector to inspect."),
    ).toBeVisible();
  });
});

import {
  ChangeDetectionStrategy,
  Component,
  OnDestroy,
  OnInit,
  inject,
  signal,
} from "@angular/core";
import { ActivatedRoute, Router } from "@angular/router";
import {
  BadgeComponent,
  ButtonDirective,
  CollapsiblePanelComponent,
} from "@aspect/ui";
import { ClockDisplayComponent } from "../../shared/clock-display.component";
import { PhaseBadgeComponent } from "../../shared/phase-badge.component";
import { SpeedDisplayComponent } from "../../shared/speed-display.component";
import { ContextPanelComponent } from "../../shared/context-panel.component";
import { DomainSelectorComponent } from "../../shared/domain-selector.component";
import { PresenceIndicatorComponent } from "../../shared/presence-indicator.component";
import { LogsDrawerComponent } from "../../shared/logs-drawer.component";
import { EngineApiService } from "../../core/engine-api.service";
import { AuditApiService, type AuditEntry } from "../../core/audit-api.service";
import { DecisionApiService } from "../../core/decision-api.service";
import type { DecisionDetail } from "../../core/decision-api.service";
import { DomainService } from "../../core/domain.service";
import { ExerciseApiService } from "../../core/exercise-api.service";
import { ExerciseWsService } from "../../core/exercise-ws.service";
import { ExerciseStore } from "../../core/exercise.store";
import { TickService } from "../../core/tick.service";
import { ScenarioPickerComponent } from "./scenario-picker";
import type { ScenarioSelection } from "./scenario-picker";
import { handleGmWsMessage } from "./gm-ws-handler";
import {
  startExercise,
  pauseExercise,
  resetExercise,
  completeExercise,
  stopExercise,
} from "./gm-engine-actions";
import { EventTimelineComponent } from "./event-timeline.component";
import { ExerciseListComponent } from "./exercise-list.component";
import { GmItemActionsComponent } from "./gm-item-actions.component";
import { SystemStatusBoardComponent } from "../../shared/system-status-board.component";
import { StressBarComponent } from "../../shared/stress-bar.component";
import type { ExerciseResponse } from "../../core/exercise-api.service";
import { Subscription } from "rxjs";

@Component({
  selector: "tfc-game-master-view",
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [ExerciseStore, TickService],
  imports: [
    BadgeComponent,
    ButtonDirective,
    CollapsiblePanelComponent,
    ClockDisplayComponent,
    PhaseBadgeComponent,
    SpeedDisplayComponent,
    ContextPanelComponent,
    ScenarioPickerComponent,
    DomainSelectorComponent,
    PresenceIndicatorComponent,
    EventTimelineComponent,
    ExerciseListComponent,
    GmItemActionsComponent,
    LogsDrawerComponent,
    SystemStatusBoardComponent,
    StressBarComponent,
  ],
  template: `
    @if (!exerciseId()) {
      <div class="flex flex-col gap-lg p-lg">
        <tfc-exercise-list
          (exerciseSelected)="onExerciseSelected($event)"
        />
        <tfc-scenario-picker (scenarioSelected)="onScenarioSelected($event)" />
      </div>
    } @else {
      <div class="exercise-layout">
        <header class="exercise-header">
          <span class="exercise-header__title">{{
            store.title() || domain.term("exercise") + " Control Panel"
          }}</span>
          <tfc-domain-selector />
          <tfc-presence-indicator [participants]="store.participants()" />
          <div class="exercise-header__clocks">
            <tfc-clock-display label="RT" [value]="store.rtClock()" />
            <tfc-speed-display [value]="store.speedFactor()" />
            <tfc-phase-badge [phase]="store.phase()" />
          </div>
        </header>

        <tfc-event-timeline
          [events]="store.events()"
          [issues]="store.issues()"
          [playTimeMs]="store.playTimeMs()"
        />

        <div class="exercise-overview">
          <tfc-gm-item-actions
            [events]="store.events()"
            [issues]="store.issues()"
            (triggerEvent)="triggerEvent($event)"
            (completeEvent)="completeEvent($event)"
            (cancelEvent)="cancelEvent($event)"
            (activateIssue)="activateIssue($event)"
            (mitigateIssue)="mitigateIssue($event)"
            (resolveIssue)="resolveIssue($event)"
          />

          <ui-collapsible-panel>
            <span panelTitle>{{ domain.term("decision") }}s</span>
            @for (decision of store.openDecisions(); track decision.id) {
              <div class="flex items-center justify-between p-sm border-b">
                <div>
                  <span class="text-sm font-medium">{{ decision.title }}</span>
                  <ui-badge variant="default">open</ui-badge>
                </div>
                <div class="flex gap-xs">
                  <button
                    uiButton
                    variant="outline"
                    size="sm"
                    (click)="viewDecision(decision.id)"
                  >
                    View
                  </button>
                  <button
                    uiButton
                    variant="destructive"
                    size="sm"
                    (click)="closeDecision(decision.id)"
                  >
                    Close
                  </button>
                </div>
              </div>
            } @empty {
              <p class="text-muted-foreground text-sm p-sm">
                No active decisions.
              </p>
            }
          </ui-collapsible-panel>
        </div>

        <div class="exercise-details">
          <ui-collapsible-panel>
            <span panelTitle>Detail Panel</span>
            @if (selectedDecision(); as detail) {
              <p class="text-sm font-medium">{{ detail.title }}</p>
              <p class="text-sm text-muted-foreground">
                {{ detail.description }}
              </p>
              @for (resp of detail.responses; track resp.id) {
                <div class="flex items-center justify-between p-sm border-b">
                  <span class="text-sm">{{ resp.participant_name }}</span>
                  <span class="text-xs text-muted-foreground">{{
                    resp.submitted_at
                  }}</span>
                </div>
              } @empty {
                <p class="text-muted-foreground text-sm">No responses yet.</p>
              }
            } @else {
              <p class="text-muted-foreground text-sm">
                Select a decision to view context.
              </p>
            }
          </ui-collapsible-panel>
          @if (store.context(); as ctx) {
            <tfc-context-panel
              [title]="ctx.title"
              [briefing]="ctx.briefing"
              [objectives]="ctx.objectives"
              [rules]="ctx.rules"
            />
          }
          <tfc-system-status-board [systems]="store.systems()" />
          <tfc-stress-bar [stress]="store.score()?.stress ?? 0" />
        </div>

        <footer class="exercise-controls">
          <div class="exercise-controls__group">
            @if (store.phase() === "setup" || store.phase() === "paused") {
              <button uiButton variant="default" (click)="onStart()">
                {{ store.phase() === "setup" ? "Start" : "Resume" }}
              </button>
            }
            @if (store.phase() === "running") {
              <button uiButton variant="outline" (click)="onPause()">
                Pause
              </button>
            }
            @if (store.phase() !== "setup") {
              <button uiButton variant="outline" (click)="onComplete()">
                Complete
              </button>
              <button uiButton variant="destructive" (click)="onStop()">
                Stop
              </button>
            }
            <button uiButton variant="destructive" (click)="onReset()">
              Reset
            </button>
          </div>
          <button class="btn" data-variant="ghost" data-size="sm" (click)="logsOpen.set(true)">Logs</button>
          <div class="exercise-controls__spacer"></div>
          <tfc-speed-display [value]="store.speedFactor()">
            <input
              type="range"
              min="0.5"
              max="10"
              step="0.5"
              [value]="store.speedFactor()"
              (input)="onSpeedChange($event)"
            />
          </tfc-speed-display>
        </footer>
      <tfc-logs-drawer [(open)]="logsOpen" [logs]="auditLog()" />
      </div>
    }
  `,
})
export class GameMasterView implements OnInit, OnDestroy {
  protected readonly store = inject(ExerciseStore);
  protected readonly domain = inject(DomainService);
  private readonly api = inject(EngineApiService);
  private readonly exerciseApi = inject(ExerciseApiService);
  private readonly decisionApi = inject(DecisionApiService);
  private readonly ws = inject(ExerciseWsService);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly auditApi = inject(AuditApiService);
  protected readonly selectedDecision = signal<DecisionDetail | null>(null);
  protected readonly exerciseId = signal<number | null>(null);
  protected readonly logsOpen = signal(false);
  protected readonly auditLog = signal<AuditEntry[]>([]);
  private sub: Subscription | null = null;
  private connSub: Subscription | null = null;
  private readonly tick = inject(TickService);

  ngOnInit(): void {
    const params = this.route.snapshot.queryParams;
