153→  /** Install default API route handlers. Call once per test. */
154→  async install(): Promise<void> {
155→    // GET /api/exercises/joinable
156→    await this.page.route("**/api/exercises/joinable", async (route) => {
157→      if (route.request().method() !== "GET") {
